{
  "name": "kg-automation",
  "image": "mcr.microsoft.com/devcontainers/python:3.11",
  "features": {
    "ghcr.io/devcontainers/features/git:1": {},
    "ghcr.io/devcontainers/features/node:1": { "version": "lts" }
  },
  "postCreateCommand": "pip install -U pip && pip install -r tooling/requirements.txt || true",
  "customizations": {
    "vscode": {
      "extensions": [
        "ms-python.python",
        "github.vscode-github-actions",
        "streetsidesoftware.code-spell-checker",
        "yzhang.markdown-all-in-one"
      ]
    }
  }
}

{
  "$schema": "https://raw.githubusercontent.com/microsoft/vscode/master/src/vs/workbench/contrib/tasks/common/tasks.schema.json",
  "version": "2.0.0",
  "tasks": [
    { "label": "docs: validate",          "type": "shell", "command": "python tooling/scripts/validate_docs.py" },
    { "label": "docs: build registries",   "type": "shell", "command": "python tooling/scripts/build_registries.py" },
    { "label": "docs: render docgraph",    "type": "shell", "command": "python tooling/scripts/render_docgraph.py" }
  ]
}
